-- Generated from supabase/seed/epa_custom.sql (CSV content).
-- Re-run npm run questions:custom-migration after editing the source file.
begin;

create temporary table epa_custom_seed on commit drop as
select *
from jsonb_to_recordset($epa_custom$[{"section":"Core","question":"What is the primary environmental concern associated with CFC and HCFC refrigerants?","option_a":"They are highly toxic when inhaled in small amounts","option_b":"They deplete stratospheric ozone","option_c":"They are the main cause of acid rain","option_d":"They create ground-level smog","correct_answer":"B","explanation":"CFCs and HCFCs contain chlorine. When these compounds reach the stratosphere, ultraviolet radiation breaks them down and releases chlorine atoms. A single chlorine atom can destroy tens of thousands of ozone molecules through a catalytic cycle. This thinning of the ozone layer allows more harmful UV radiation to reach the Earth’s surface. HFCs do not contain chlorine and therefore have zero ozone depletion potential.","source_ref":"EPA Test Topics – Environmental Impacts; Montreal Protocol"},{"section":"Core","question":"Under Section 608 of the Clean Air Act, knowingly venting CFC, HCFC, or non-exempt substitute refrigerants during maintenance, service, repair, or disposal is:","option_a":"Allowed if the charge is under 5 pounds","option_b":"Strictly prohibited","option_c":"Allowed only when recovery equipment is unavailable","option_d":"Allowed during system retirement","correct_answer":"B","explanation":"The Clean Air Act prohibits the knowing release of ozone-depleting refrigerants and most substitute refrigerants into the atmosphere. This venting prohibition applies during servicing, maintenance, repair, and disposal of appliances. There are very limited exceptions (for example, de minimis releases that occur despite good-faith recovery efforts), but intentional venting is illegal and can result in significant civil penalties.","source_ref":"40 CFR 82.154; EPA Test Topics – Venting prohibition"},{"section":"Core","question":"Which statement about ozone depletion potential (ODP) is correct?","option_a":"HFCs have higher ODP than HCFCs","option_b":"CFCs generally have higher ODP than HCFCs, which in turn have higher ODP than HFCs","option_c":"All common refrigerants have roughly the same ODP","option_d":"Only hydrocarbon refrigerants have ODP values","correct_answer":"B","explanation":"ODP is a relative measure of how much a substance depletes stratospheric ozone compared to CFC-11 (which is assigned an ODP of 1.0). CFCs have the highest ODP values, HCFCs have significantly lower but still measurable ODP, and HFCs/HFOs have zero ODP because they contain no chlorine or bromine.","source_ref":"EPA Test Topics – Environmental Impacts"},{"section":"Core","question":"According to EPA definitions, “recovery” means:","option_a":"Cleaning used refrigerant so it can be reused in the same system","option_b":"Removing refrigerant from an appliance and storing it in an external container without necessarily testing or processing it","option_c":"Processing refrigerant to meet AHRI 700 purity standards so it can be sold","option_d":"Destroying refrigerant so it cannot be reused","correct_answer":"B","explanation":"Recovery is the process of removing refrigerant from a system and placing it into an external cylinder or container. At this stage the refrigerant is not required to meet any purity standard. It may later be recycled (for reuse by the same owner) or sent to a reclaimer.","source_ref":"EPA Test Topics – Three R Definitions"},{"section":"Core","question":"“Recycling” of refrigerant typically means:","option_a":"Returning the refrigerant to the original manufacturer","option_b":"Cleaning refrigerant for reuse in equipment owned by the same person using equipment that reduces contaminants","option_c":"Processing refrigerant to full AHRI 700 specifications so it can be sold to anyone","option_d":"Incinerating the refrigerant","correct_answer":"B","explanation":"Recycling is usually performed on-site or at a local service facility. It involves using recovery/recycling equipment to reduce moisture, oil, acidity, and non-condensables so the refrigerant can be charged back into equipment belonging to the same owner. It does not require meeting the full AHRI 700 reclamation standard.","source_ref":"EPA Test Topics – Three R Definitions"},{"section":"Core","question":"Reclaimed refrigerant must meet which purity standard before it can be sold to a new owner?","option_a":"ASHRAE Standard 15","option_b":"AHRI Standard 700","option_c":"EPA Section 608 purity guidelines","option_d":"DOT cylinder standards only","correct_answer":"B","explanation":"Reclamation is the process of reprocessing used refrigerant to at least the purity levels specified in AHRI Standard 700 (formerly ARI 700). Only EPA-certified reclaimers can perform this service and legally sell the refrigerant to a new owner.","source_ref":"EPA Test Topics – Section 608 Regulations; AHRI 700"},{"section":"Core","question":"Reusable recovery cylinders are typically color-coded:","option_a":"Solid yellow","option_b":"Gray body with a yellow top shoulder","option_c":"Green body with a red top","option_d":"Blue body with a white top","correct_answer":"B","explanation":"Industry standard for recovery cylinders is a gray body with a yellow top. This color scheme quickly distinguishes them from disposable cylinders and from virgin refrigerant cylinders. Technicians should also verify the cylinder is DOT-approved and within its hydrostatic test date.","source_ref":"EPA Test Topics – Safety"},{"section":"Core","question":"A recovery cylinder should never be filled beyond what percentage of its internal volume?","option_a":"60%","option_b":"70%","option_c":"80%","option_d":"95%","correct_answer":"C","explanation":"Refrigerant liquid expands significantly as temperature rises. Filling a cylinder beyond 80% of its water capacity leaves insufficient vapor space (headspace) and can cause the cylinder to become liquid-full, creating extremely high hydrostatic pressure that can rupture the cylinder.","source_ref":"EPA Test Topics – Safety"},{"section":"Core","question":"The Section 608 sales restriction requires that regulated refrigerants may only be sold to:","option_a":"Any licensed contractor","option_b":"Technicians who are Section 608 certified or to employers who employ certified technicians","option_c":"Homeowners for DIY use","option_d":"Anyone who signs a waiver","correct_answer":"B","explanation":"It is illegal to sell CFC, HCFC, or non-exempt substitute refrigerants to someone who is not certified (or whose employer does not employ a certified technician). Sellers must verify certification status.","source_ref":"EPA Test Topics – Sales Restriction; 40 CFR 82.154"},{"section":"Core","question":"Which statement about “drop-in” refrigerant replacements is most accurate?","option_a":"Many true drop-in replacements exist for R-22 systems","option_b":"True drop-in replacements are essentially non-existent because of lubricant and material compatibility issues","option_c":"All HFCs can be used as direct drop-ins for CFCs","option_d":"Hydrocarbon refrigerants are approved drop-ins for most systems","correct_answer":"B","explanation":"Although some refrigerants are marketed as “drop-ins,” true drop-in performance without any system changes is rare. Most replacements require oil changes (e.g., to POE), seal replacements, or other modifications due to differences in solubility, pressure, and material compatibility.","source_ref":"EPA Test Topics – Substitute Refrigerants and oils"},{"section":"Core","question":"The Montreal Protocol is best described as:","option_a":"A U.S. federal regulation under the Clean Air Act","option_b":"An international treaty that controls and phases out the production of ozone-depleting substances","option_c":"An ASHRAE safety standard for machinery rooms","option_d":"A Department of Transportation rule for shipping cylinders","correct_answer":"B","explanation":"The Montreal Protocol (1987) is the global agreement that established schedules for phasing out CFCs, Halons, HCFCs, and other ozone-depleting substances. The U.S. Clean Air Act implements the Protocol’s requirements domestically.","source_ref":"EPA Test Topics – Clean Air Act and Montreal Protocol"},{"section":"Core","question":"When using nitrogen for leak testing or purging, the technician must always:","option_a":"Use pure nitrogen with no additional devices","option_b":"Use a pressure regulator and a relief valve","option_c":"Mix nitrogen with oxygen for better detection","option_d":"Pressurize the system to at least 300 psig","correct_answer":"B","explanation":"Nitrogen cylinders contain very high pressure. A regulator is required to reduce pressure to a safe working level, and a relief valve protects the system from accidental over-pressurization.","source_ref":"EPA Test Topics – Safety"},{"section":"Core","question":"Disposable refrigerant cylinders:","option_a":"May be refilled by a certified technician if they pass visual inspection","option_b":"Must never be refilled","option_c":"Can be used as recovery vessels in an emergency","option_d":"Are required to be painted gray and yellow","correct_answer":"B","explanation":"Disposable cylinders are manufactured for one-time use only. Refilling them is dangerous and prohibited because they lack the safety features and wall thickness of reusable recovery cylinders.","source_ref":"EPA Test Topics – Safety"},{"section":"Core","question":"After completing service on a system, the technician must evacuate the system to remove:","option_a":"Only residual oil","option_b":"Air and moisture","option_c":"Only non-condensable gases","option_d":"Only excess refrigerant","correct_answer":"B","explanation":"Air (non-condensables) and moisture cause high head pressure, acid formation, copper plating, and oil breakdown. Proper dehydration/evacuation to the required micron level is essential before recharging.","source_ref":"EPA Test Topics – Dehydration Evacuation"},{"section":"Core","question":"Which of the following are recognized health or safety risks from refrigerant exposure?","option_a":"Oxygen deprivation (asphyxiation)","option_b":"Frostbite from liquid contact","option_c":"Cardiac sensitization","option_d":"All of the above","correct_answer":"D","explanation":"Refrigerants can displace oxygen in confined spaces, cause severe frostbite on skin or eyes, and some can sensitize the heart to arrhythmias. Proper PPE and ventilation are required.","source_ref":"EPA Test Topics – Safety"},{"section":"Core","question":"Self-contained recovery equipment is defined as equipment that:","option_a":"Uses the appliance’s own compressor to remove refrigerant","option_b":"Has its own independent compressor or pumping mechanism to remove refrigerant","option_c":"Can only be used on systems under 5 pounds","option_d":"Is the same as a vacuum pump","correct_answer":"B","explanation":"Self-contained (active) recovery units have their own means of removing refrigerant and do not rely on the system’s compressor.","source_ref":"EPA Test Topics – Section 608 Regulations"},{"section":"Core","question":"System-dependent (passive) recovery equipment:","option_a":"Contains its own compressor","option_b":"Relies on the appliance’s compressor or on the pressure inside the system to push refrigerant out","option_c":"Is required on every system over 50 pounds","option_d":"Can recover refrigerant faster than self-contained units","correct_answer":"B","explanation":"System-dependent recovery uses the system itself (running compressor or system pressure) to move refrigerant into a recovery container. It is limited to systems containing 15 pounds or less of refrigerant.","source_ref":"EPA Test Topics – Section 608 Regulations"},{"section":"Core","question":"Civil penalties for Clean Air Act Section 608 violations can currently exceed:","option_a":"\u00245,000 per day","option_b":"\u002415,000 per day","option_c":"\u002440,000+ per day per violation","option_d":"\u0024100 per occurrence","correct_answer":"C","explanation":"Penalties are adjusted periodically for inflation and can be very substantial for knowing violations.","source_ref":"EPA Test Topics – Clean Air Act"},{"section":"Core","question":"When shipping recovered refrigerant, the cylinder must be labeled with:","option_a":"Only the technician’s name","option_b":"The refrigerant identification and proper DOT shipping classification","option_c":"A company logo only","option_d":"No special labels if it is going to a reclaimer","correct_answer":"B","explanation":"DOT regulations require proper shipping names, hazard class labels, and identification numbers on cylinders containing refrigerant.","source_ref":"EPA Test Topics – Shipping"},{"section":"Core","question":"Fractionation of a refrigerant blend occurs when:","option_a":"The blend is intentionally mixed with another refrigerant","option_b":"Different components of the blend leak at different rates, changing the remaining composition","option_c":"The refrigerant is recycled on-site","option_d":"The refrigerant reaches its critical temperature","correct_answer":"B","explanation":"Zeotropic blends have components with different boiling points. As the blend leaks, the more volatile components preferentially escape, altering the composition and pressure-temperature relationship of the remaining refrigerant.","source_ref":"EPA Test Topics – Substitute Refrigerants"},{"section":"Core","question":"R-12 is classified as which type of refrigerant?","option_a":"HFC","option_b":"HCFC","option_c":"CFC","option_d":"HFO","correct_answer":"C","explanation":"R-12 (dichlorodifluoromethane) is a chlorofluorocarbon and has a high ozone depletion potential.","source_ref":"EPA Test Topics – Identification of refrigerants"},{"section":"Core","question":"R-22 is classified as which type of refrigerant?","option_a":"CFC","option_b":"HCFC","option_c":"HFC","option_d":"HC","correct_answer":"B","explanation":"R-22 (chlorodifluoromethane) is a hydrochlorofluorocarbon. It has a lower ODP than CFCs but is still being phased out.","source_ref":"EPA Test Topics – Identification of refrigerants"},{"section":"Core","question":"R-134a is classified as which type of refrigerant?","option_a":"CFC","option_b":"HCFC","option_c":"HFC","option_d":"HFO","correct_answer":"C","explanation":"R-134a contains no chlorine and therefore has zero ODP. It is a hydrofluorocarbon.","source_ref":"EPA Test Topics – Identification of refrigerants"},{"section":"Core","question":"Most HFC refrigerants require which type of lubricant?","option_a":"Mineral oil","option_b":"Alkylbenzene","option_c":"Polyolester (POE) oil","option_d":"Silicone oil","correct_answer":"C","explanation":"HFCs have poor solubility with traditional mineral oils. Polyolester (POE) lubricants are the standard choice for most HFC systems.","source_ref":"EPA Test Topics – Substitute Refrigerants and oils"},{"section":"Core","question":"Before using any recovery cylinder, a technician should verify:","option_a":"That it is the cheapest available","option_b":"That it is DOT-approved, within its hydrostatic test date, and properly color-coded","option_c":"That it has never been used before","option_d":"That it is painted solid yellow","correct_answer":"B","explanation":"Using a damaged, out-of-date, or non-approved cylinder creates serious safety risks. Visual inspection and verification of the test date are mandatory good practices.","source_ref":"EPA Test Topics – Safety"},{"section":"TypeI","question":"Under EPA Section 608, a “small appliance” is defined as:","option_a":"Any system containing 15 pounds or less of refrigerant","option_b":"A hermetically sealed appliance that is factory-charged with 5 pounds or less of refrigerant","option_c":"Any residential air-conditioning system","option_d":"Any system that uses R-134a","correct_answer":"B","explanation":"The regulatory definition requires both conditions: the appliance must be fully manufactured, charged, and hermetically sealed in a factory, and it must contain 5 pounds or less of refrigerant.","source_ref":"EPA Test Topics – Type 1 Definition of small appliance"},{"section":"TypeI","question":"When recovering refrigerant from a small appliance with a non-operating compressor using a system-dependent recovery device, the technician must:","option_a":"Recover only from the high-side access fitting","option_b":"Install access fittings on both the high and low sides of the system","option_c":"Never apply heat to the compressor","option_d":"Use only a self-contained recovery machine","correct_answer":"B","explanation":"With a non-operating compressor, refrigerant can be trapped on both sides of the system. Accessing both the high and low sides allows more complete recovery when using passive methods.","source_ref":"EPA Test Topics – Type 1 Recovery Techniques"},{"section":"TypeI","question":"For recovery equipment manufactured after November 15, 1993, the required recovery efficiency from a small appliance when the compressor is operating is:","option_a":"80% of the nameplate charge","option_b":"90% of the nameplate charge","option_c":"95% of the nameplate charge","option_d":"Recovery to 0 psig only","correct_answer":"B","explanation":"When the compressor is running, post-1993 recovery devices must be capable of recovering 90% of the refrigerant charge from a small appliance.","source_ref":"EPA Test Topics – Type 1 Evacuation requirements"},{"section":"TypeI","question":"For recovery equipment manufactured after November 15, 1993, when the compressor of a small appliance is not operating, the required recovery level is:","option_a":"90% of the charge","option_b":"80% of the charge","option_c":"Recovery to 4 inches of mercury vacuum","option_d":"Recovery to 0 psig only","correct_answer":"B","explanation":"When the compressor is inoperative, the requirement drops to 80% of the nameplate charge for post-1993 equipment.","source_ref":"EPA Test Topics – Type 1 Evacuation requirements"},{"section":"TypeI","question":"When using a system-dependent recovery device on a small appliance that has an operating compressor, the technician should:","option_a":"Turn the compressor off before starting recovery","option_b":"Run the compressor to help push refrigerant into the recovery container","option_c":"Replace the compressor before recovering","option_d":"Bypass the compressor with a jumper hose","correct_answer":"B","explanation":"An operating compressor can actively pump refrigerant toward the recovery device, improving recovery speed and efficiency in passive recovery setups.","source_ref":"EPA Test Topics – Type 1 Recovery Techniques"},{"section":"TypeI","question":"Solderless piercing valves that are installed on small appliances for service should:","option_a":"Be left permanently in place after service","option_b":"Be removed after service whenever possible","option_c":"Be replaced only with Schrader-type valves","option_d":"Never be used on copper tubing","correct_answer":"B","explanation":"Piercing valves can develop leaks over time. Best practice is to remove them once service is complete if the system will remain in use.","source_ref":"EPA Test Topics – Type 1 Recovery Techniques"},{"section":"TypeI","question":"R-134a became the primary replacement for which refrigerant in many small appliances?","option_a":"R-22","option_b":"R-12","option_c":"R-410A","option_d":"R-11","correct_answer":"B","explanation":"Domestic refrigerators, freezers, and many other small appliances previously used R-12. R-134a was the most common replacement.","source_ref":"EPA Test Topics – Type 1 HFC-134a as substitute"},{"section":"TypeI","question":"System-dependent (passive) recovery equipment:","option_a":"Has its own built-in compressor","option_b":"Relies on the system’s pressure or the appliance’s compressor to move refrigerant","option_c":"Is required for all systems larger than 15 pounds","option_d":"Can only recover vapor, never liquid","correct_answer":"B","explanation":"Passive recovery does not have an independent pumping mechanism; it uses existing system pressure or the running compressor.","source_ref":"EPA Test Topics – Type 1 Recovery Techniques"},{"section":"TypeI","question":"A technician can detect non-condensable gases in a recovered refrigerant or system by:","option_a":"Visually inspecting the sight glass only","option_b":"Comparing the system pressure to the expected pressure on a pressure-temperature chart for the measured temperature","option_c":"Smelling the refrigerant vapor","option_d":"Weighing the recovery cylinder before and after","correct_answer":"B","explanation":"If the measured pressure is higher than what the P-T chart indicates for the actual temperature, non-condensables (usually air) are likely present.","source_ref":"EPA Test Topics – Type 1 Recovery Techniques"},{"section":"TypeI","question":"Applying controlled heat to a small appliance during passive recovery is done primarily to:","option_a":"Increase the pressure to dangerous levels","option_b":"Help release refrigerant that is dissolved in the oil or trapped in low-temperature components","option_c":"Destroy any remaining moisture","option_d":"Speed up compressor burnout","correct_answer":"B","explanation":"Gentle heat raises the vapor pressure of the refrigerant and helps drive it out of the oil and colder parts of the system.","source_ref":"EPA Test Topics – Type 1 Recovery Techniques"},{"section":"TypeI","question":"When recovering from a small appliance with an inoperative compressor, access fittings should be installed:","option_a":"Only on the high side","option_b":"On both the high and low sides","option_c":"Only on the low side","option_d":"Only after the system has been evacuated","correct_answer":"B","explanation":"Both sides must be accessible to recover refrigerant that may be isolated by the non-operating compressor.","source_ref":"EPA Test Topics – Type 1 Recovery Techniques"},{"section":"TypeI","question":"The recovery percentage requirements for small appliances depend mainly on:","option_a":"The brand of recovery machine only","option_b":"Whether the compressor is operating and the manufacture date of the recovery equipment","option_c":"The ambient temperature only","option_d":"The type of oil in the system","correct_answer":"B","explanation":"EPA rules set different recovery efficiencies based on compressor status and whether the recovery equipment was made before or after November 15, 1993.","source_ref":"EPA Test Topics – Type 1 Evacuation requirements"},{"section":"TypeI","question":"Which of the following is a classic example of a small appliance under EPA rules?","option_a":"A 5-ton rooftop package unit","option_b":"A household refrigerator or freezer","option_c":"A 100-ton centrifugal chiller","option_d":"A supermarket parallel rack system","correct_answer":"B","explanation":"Household refrigerators and freezers are factory-sealed and contain well under 5 pounds of refrigerant.","source_ref":"EPA Test Topics – Type 1 Definition"},{"section":"TypeI","question":"Using a vacuum pump connected to a non-pressurized recovery container to remove refrigerant from a small appliance is an example of:","option_a":"Self-contained recovery","option_b":"System-dependent (passive) recovery","option_c":"Reclamation","option_d":"Liquid recovery only","correct_answer":"B","explanation":"This method relies on the vacuum pump rather than a dedicated recovery compressor and is considered passive/system-dependent.","source_ref":"EPA Test Topics – Type 1 Recovery Techniques"},{"section":"TypeI","question":"A technician who services small appliances must hold at least which certification?","option_a":"Type II only","option_b":"Type I or Universal","option_c":"Type III only","option_d":"No certification is required for small appliances","correct_answer":"B","explanation":"Type I certification covers small appliances. Universal certification also includes Type I privileges.","source_ref":"40 CFR 82.161"},{"section":"TypeI","question":"One reason piercing valves should be removed after service is:","option_a":"They are illegal to leave in place","option_b":"They have a higher long-term leak potential than properly brazed or mechanical fittings","option_c":"They void the manufacturer warranty automatically","option_d":"They can only be used once","correct_answer":"B","explanation":"The rubber or elastomer seals in many piercing valves can degrade or loosen over time, creating a leak path.","source_ref":"EPA Test Topics – Type 1"},{"section":"TypeI","question":"The maximum refrigerant charge for an appliance to be classified as a small appliance is:","option_a":"5 pounds","option_b":"15 pounds","option_c":"50 pounds","option_d":"200 pounds","correct_answer":"A","explanation":"The regulatory cutoff is 5 pounds of refrigerant.","source_ref":"EPA Test Topics – Type 1 Definition"},{"section":"TypeI","question":"When the compressor is operating and post-1993 recovery equipment is used, the recovery target for a small appliance is:","option_a":"80% of the charge","option_b":"90% of the charge","option_c":"Recovery to atmospheric pressure only","option_d":"Recovery to 15 inches of mercury","correct_answer":"B","explanation":"90% recovery is required when the compressor is running.","source_ref":"EPA Test Topics – Type 1"},{"section":"TypeI","question":"At high temperatures, refrigerants can decompose and produce:","option_a":"Only harmless water vapor","option_b":"Toxic or corrosive compounds such as hydrochloric and hydrofluoric acids","option_c":"Additional ozone","option_d":"Inert nitrogen","correct_answer":"B","explanation":"Open flames or extreme heat can break down refrigerants into dangerous acids and phosgene-like compounds.","source_ref":"EPA Test Topics – Type 1 Safety"},{"section":"TypeI","question":"Mixing different refrigerants during recovery from small appliances is:","option_a":"Acceptable if they are both HFCs","option_b":"Strictly discouraged and should be avoided","option_c":"Required for proper reclamation","option_d":"Only a problem with CFCs","correct_answer":"B","explanation":"Mixing refrigerants contaminates the recovered material and makes reclamation more difficult or impossible.","source_ref":"EPA Test Topics – General recovery principles + Type 1"},{"section":"TypeI","question":"System-dependent recovery is permitted on small appliances primarily because:","option_a":"They always use R-134a","option_b":"They contain 5 pounds or less of refrigerant (well under the 15-pound limit)","option_c":"EPA requires passive recovery on all small systems","option_d":"They have no compressors","correct_answer":"B","explanation":"The 15-pound limit for system-dependent equipment makes all true small appliances eligible for passive recovery methods.","source_ref":"Related regulatory limit"},{"section":"TypeI","question":"After recovering refrigerant from a small appliance that will be disposed of, the technician must:","option_a":"Vent any remaining traces of refrigerant","option_b":"Recover the required percentage of the charge according to the applicable rule","option_c":"Leave the system under vacuum permanently","option_d":"Fill the system with compressed air","correct_answer":"B","explanation":"The technician is obligated to meet the recovery efficiency requirements before disposal.","source_ref":"EPA Test Topics – Type 1"},{"section":"TypeI","question":"Which statement is correct about recovery methods on small appliances?","option_a":"Only vapor recovery is ever allowed","option_b":"Both liquid and vapor recovery techniques may be appropriate depending on the situation and equipment","option_c":"Liquid recovery is completely prohibited","option_d":"Recovery is optional if the charge is under 3 pounds","correct_answer":"B","explanation":"Technicians may use whatever method (within the rules) achieves the required recovery percentage.","source_ref":"EPA Test Topics – Type 1"},{"section":"TypeII","question":"The annual leak-rate threshold that triggers mandatory repair for comfort-cooling appliances containing 50 or more pounds of refrigerant is:","option_a":"5% of the full charge per year","option_b":"10% of the full charge per year","option_c":"20% of the full charge per year","option_d":"30% of the full charge per year","correct_answer":"B","explanation":"Comfort-cooling appliances (office AC, residential comfort cooling, etc.) have a 10% annual leak-rate threshold.","source_ref":"EPA Test Topics – Type 2 Leak repair requirements"},{"section":"TypeII","question":"The annual leak-rate threshold for commercial refrigeration equipment (≥50 lbs) is:","option_a":"10%","option_b":"20%","option_c":"30%","option_d":"40%","correct_answer":"B","explanation":"Commercial refrigeration (display cases, walk-ins, etc.) has a 20% threshold.","source_ref":"EPA Test Topics – Type 2"},{"section":"TypeII","question":"The annual leak-rate threshold for industrial process refrigeration (≥50 lbs) is:","option_a":"10%","option_b":"20%","option_c":"30%","option_d":"50%","correct_answer":"C","explanation":"Industrial process refrigeration has the highest threshold at 30%.","source_ref":"EPA Test Topics – Type 2"},{"section":"TypeII","question":"System-dependent recovery equipment may not be used on appliances that contain more than:","option_a":"5 pounds of refrigerant","option_b":"15 pounds of refrigerant","option_c":"50 pounds of refrigerant","option_d":"200 pounds of refrigerant","correct_answer":"B","explanation":"EPA prohibits the use of system-dependent recovery devices on systems with more than 15 pounds of refrigerant.","source_ref":"EPA Test Topics – Type 2 Recovery Requirements"},{"section":"TypeII","question":"The preferred gas for leak testing high-pressure systems is:","option_a":"Pure refrigerant from a cylinder","option_b":"Oxygen or compressed air","option_c":"Dry nitrogen (or nitrogen with a small tracer amount of R-22)","option_d":"Carbon dioxide","correct_answer":"C","explanation":"Nitrogen is inert, inexpensive, and safe when properly regulated. Adding a small amount of R-22 can make electronic leak detectors more effective while still minimizing refrigerant release.","source_ref":"EPA Test Topics – Type 2 Leak Detection"},{"section":"TypeII","question":"Beginning the recovery process by removing liquid refrigerant:","option_a":"Is slower than vapor-only recovery","option_b":"Significantly speeds up the overall recovery process","option_c":"Is only allowed on low-pressure systems","option_d":"Damages most recovery machines","correct_answer":"B","explanation":"Liquid has much higher density than vapor, so removing liquid first transfers the majority of the charge quickly.","source_ref":"EPA Test Topics – Type 2 Recovery Techniques"},{"section":"TypeII","question":"After the recovery machine reaches the required vacuum level, the technician should:","option_a":"Immediately disconnect the hoses and open the system","option_b":"Wait several minutes to observe whether system pressure rises","option_c":"Break the vacuum with high-pressure nitrogen right away","option_d":"Add oil to the compressor immediately","correct_answer":"B","explanation":"A rise in pressure usually indicates that liquid refrigerant is still boiling off in the system or in the oil. Additional recovery time is then needed.","source_ref":"EPA Test Topics – Type 2 Recovery Techniques"},{"section":"TypeII","question":"Under EPA rules, “major” repairs generally include work that involves:","option_a":"Simply replacing a liquid-line filter drier","option_b":"Opening the refrigeration circuit in a significant way (compressor, condenser, evaporator replacement, etc.)","option_c":"Only repairs that take more than two hours","option_d":"Only leak repairs on the high side","correct_answer":"B","explanation":"Major repairs are those that require opening the system beyond minor service operations and typically trigger stricter evacuation requirements.","source_ref":"EPA Test Topics – Type 2 Definition of major repairs"},{"section":"TypeII","question":"Before charging or recharging a high-pressure appliance, the technician should:","option_a":"Assume the system is leak-free if it held pressure overnight","option_b":"Perform a leak test","option_c":"Only check the low-side pressure","option_d":"Add a full charge and then look for leaks","correct_answer":"A","explanation":"Leak testing before charging prevents releasing a full charge into the atmosphere if a leak exists.","source_ref":"EPA Test Topics – Type 2 Leak Detection"},{"section":"TypeII","question":"Common signs that a high-pressure system is leaking include:","option_a":"Excessively high superheat","option_b":"Visible oil stains or traces around fittings and hermetic components","option_c":"Both A and B","option_d":"Neither A nor B","correct_answer":"C","explanation":"High superheat can indicate loss of charge, and oil traces often mark the location of a refrigerant leak.","source_ref":"EPA Test Topics – Type 2 Leak Detection"},{"section":"TypeII","question":"When a recovery machine is switched from one refrigerant to another, the technician must:","option_a":"Do nothing if the refrigerants are similar","option_b":"Follow proper procedures to minimize cross-contamination and residual emissions","option_c":"Only change the filter drier","option_d":"Run the machine empty for 30 seconds","correct_answer":"B","explanation":"Residual refrigerant left in the machine can contaminate the next refrigerant recovered. Proper pump-out or flush procedures are required.","source_ref":"EPA Test Topics – Type 2 Recovery Techniques"},{"section":"TypeII","question":"Recovery evacuation requirements for high-pressure appliances vary according to:","option_a":"Only the type of refrigerant","option_b":"Whether the repair is major or non-major, whether the system is leaky, the charge size, and the manufacture date of the recovery equipment","option_c":"Only the ambient temperature","option_d":"Only the technician’s certification level","correct_answer":"A","explanation":"EPA sets different vacuum levels based on these multiple factors.","source_ref":"EPA Test Topics – Type 2 Recovery Requirements"},{"section":"TypeII","question":"Hydrocarbon refrigerants are:","option_a":"Approved by EPA as universal drop-in replacements for R-22","option_b":"Not approved for retrofitting most existing systems under current EPA rules","option_c":"Required in all new Type II equipment","option_d":"Chemically identical to HFCs","correct_answer":"B","explanation":"While hydrocarbons are used in some new equipment designed for them, they are not approved as drop-in replacements for existing CFC or HCFC systems.","source_ref":"EPA Test Topics – Type 2 Refrigeration"},{"section":"TypeII","question":"ASHRAE Standard 15 requires that machinery rooms containing refrigeration equipment have:","option_a":"Only fire extinguishers","option_b":"Oxygen deprivation sensors (and additional sensors for certain refrigerants)","option_c":"No special monitoring","option_d":"Only combustible gas detectors for all refrigerants","correct_answer":"B","explanation":"Oxygen deprivation monitoring is required because most refrigerants can displace oxygen. Some refrigerants have additional specific sensor requirements.","source_ref":"EPA Test Topics – Type 2 Safety"},{"section":"TypeII","question":"In a typical high-pressure refrigeration system, the receiver contains refrigerant in the:","option_a":"High-pressure vapor state","option_b":"High-pressure liquid state","option_c":"Low-pressure vapor state","option_d":"Low-pressure liquid state","correct_answer":"B","explanation":"The receiver is located after the condenser and stores high-pressure liquid refrigerant.","source_ref":"EPA Test Topics – Type 2 Refrigeration components"},{"section":"TypeII","question":"The accumulator in a high-pressure system is normally located:","option_a":"On the liquid line after the receiver","option_b":"On the suction line before the compressor","option_c":"Inside the condenser","option_d":"On the discharge line","correct_answer":"B","explanation":"The accumulator protects the compressor by trapping any liquid refrigerant that might leave the evaporator.","source_ref":"EPA Test Topics – Type 2"},{"section":"TypeII","question":"Stricter recovery vacuum levels generally apply when:","option_a":"The system is undergoing a non-major repair and is not leaking","option_b":"The system is being disposed of or is undergoing a major repair","option_c":"The system uses only HFC refrigerants","option_d":"The ambient temperature is below 70°F","correct_answer":"B","explanation":"Disposal and major repairs trigger the most stringent evacuation requirements.","source_ref":"EPA Test Topics – Type 2 Recovery Requirements"},{"section":"TypeII","question":"In the hierarchy of leak-test gases, pure refrigerant ranks:","option_a":"As the most preferred option","option_b":"As the least preferred option among the common choices","option_c":"Equal to dry nitrogen","option_d":"Only acceptable for systems under 5 pounds","correct_answer":"B","explanation":"EPA and good practice prefer nitrogen (or nitrogen + trace refrigerant) over pure refrigerant to minimize emissions during leak testing.","source_ref":"EPA Test Topics – Type 2 Leak Detection"},{"section":"TypeII","question":"Lack of an available certified technician is generally:","option_a":"A valid reason for an automatic extension of the leak-repair deadline","option_b":"Not considered a valid reason for extending the leak-repair deadline","option_c":"Grounds for a 90-day extension","option_d":"Only applicable to Type III systems","correct_answer":"B","explanation":"EPA rules carefully limit what circumstances allow an extension of the repair timeline.","source_ref":"Related to Type 2 leak repair rules"},{"section":"TypeII","question":"Pressure-temperature charts are essential tools for:","option_a":"Identifying the type of refrigerant and detecting non-condensables","option_b":"Measuring only superheat and subcooling","option_c":"Replacing the need for manifold gauges","option_d":"Determining the correct oil type","correct_answer":"A","explanation":"Comparing actual pressure to the expected saturation pressure at a known temperature reveals whether the refrigerant is pure or contaminated with non-condensables.","source_ref":"EPA Test Topics – Type 2 Refrigeration"},{"section":"TypeII","question":"Energizing a hermetic compressor while the system is under deep vacuum can:","option_a":"Help the recovery process","option_b":"Cause the motor windings to arc or overheat because the lack of refrigerant reduces cooling and dielectric strength","option_c":"Improve oil return","option_d":"Be used as a standard diagnostic method","correct_answer":"B","explanation":"Without refrigerant vapor to cool the motor and provide dielectric strength, the windings can fail.","source_ref":"EPA Test Topics – Type 2 Safety"},{"section":"TypeII","question":"When a system containing 50 or more pounds of refrigerant exceeds its applicable leak-rate threshold, the owner must:","option_a":"Continue normal operation while documenting the leak","option_b":"Repair the appliance so the leak rate falls below the threshold, or retrofit or retire the appliance","option_c":"Vent the remaining refrigerant and replace the system immediately","option_d":"Only notify the EPA","correct_answer":"A","explanation":"The owner has the obligation to fix the leak or take the system out of service / retrofit it.","source_ref":"EPA Test Topics – Type 2 Leak repair requirements"},{"section":"TypeII","question":"Recordkeeping related to leak inspections and repairs on systems with 50 or more pounds of refrigerant is:","option_a":"Completely optional","option_b":"Required by EPA regulations","option_c":"Required only for CFC systems","option_d":"Required only for Type III equipment","correct_answer":"B","explanation":"Owners and operators must maintain records of leak rates, inspections, and repairs for the required retention period.","source_ref":"EPA Test Topics – Type 2 Leak repair recordkeeping"},{"section":"TypeII","question":"Chilling the recovery cylinder during the recovery process:","option_a":"Has no effect","option_b":"Helps keep the cylinder pressure lower, which improves the recovery rate","option_c":"Is prohibited by EPA","option_d":"Only works with low-pressure refrigerants","correct_answer":"B","explanation":"Lower cylinder pressure increases the pressure differential and speeds transfer of refrigerant.","source_ref":"EPA Test Topics – Type 2 Recovery Techniques"},{"section":"TypeII","question":"Safely applying heat to an appliance during recovery can:","option_a":"Help drive refrigerant out of the oil and colder components","option_b":"Create a dangerous over-pressure condition if not carefully controlled","option_c":"Both A and B are true","option_d":"Neither A nor B is true","correct_answer":"C","explanation":"Controlled heat is useful; uncontrolled heat is hazardous.","source_ref":"EPA Test Topics – Type 2 Recovery Techniques"},{"section":"TypeIII","question":"The rupture disc on a typical low-pressure centrifugal chiller is designed to burst at approximately:","option_a":"5 psig","option_b":"15 psig","option_c":"30 psig","option_d":"150 psig","correct_answer":"B","explanation":"Most low-pressure chillers use a rupture disc rated around 15 psig to protect the system from over-pressure while remaining well below the design pressure of the vessels.","source_ref":"EPA Test Topics – Type 3 / standard industry practice aligned with topics"},{"section":"TypeIII","question":"The preferred method for raising pressure in a charged low-pressure chiller for leak testing is:","option_a":"Pressurizing with nitrogen to 50 psig or higher","option_b":"Using controlled hot water or the chiller’s built-in heating/pressurization system","option_c":"Using an open flame on the evaporator","option_d":"Pressurizing with pure oxygen","correct_answer":"B","explanation":"Hot water or a dedicated heating device raises pressure gently and safely without exceeding the low rupture-disc setting.","source_ref":"EPA Test Topics – Type 3 Leak Detection"},{"section":"TypeIII","question":"When leak-testing a low-pressure centrifugal chiller, the pressure should be kept low enough to avoid:","option_a":"Activating the high-pressure switch","option_b":"Bursting the rupture disc","option_c":"Opening the purge unit","option_d":"Tripping the oil differential switch","correct_answer":"B","explanation":"Exceeding the rupture-disc setting will release the entire charge.","source_ref":"EPA Test Topics – Type 3"},{"section":"TypeIII","question":"Frequent or continuous operation of the purge unit on a low-pressure chiller is usually a sign of:","option_a":"Normal efficient operation","option_b":"Air (non-condensables) leaking into the system","option_c":"Overcharging of refrigerant","option_d":"Insufficient oil in the compressor","correct_answer":"B","explanation":"The purge unit removes air that has entered the system. Excessive purge activity indicates a leak allowing air in.","source_ref":"EPA Test Topics – Type 3 Leak Detection"},{"section":"TypeIII","question":"Before removing oil from a low-pressure chiller, the oil should be heated to approximately:","option_a":"70°F","option_b":"100°F","option_c":"130°F","option_d":"200°F","correct_answer":"C","explanation":"Heating the oil to about 130°F reduces the amount of refrigerant dissolved in the oil, minimizing refrigerant loss when the oil is drained.","source_ref":"EPA Test Topics – Type 3 Recovery Techniques"},{"section":"TypeIII","question":"When charging a low-pressure centrifugal chiller, refrigerant should first be introduced as:","option_a":"Liquid into the condenser","option_b":"Vapor into the evaporator side","option_c":"Liquid directly into the compressor suction","option_d":"A mixture of liquid and vapor into the liquid line","correct_answer":"B","explanation":"Introducing vapor first raises the system pressure above the freezing point of water and prevents water in the tubes from freezing when liquid refrigerant is later added.","source_ref":"EPA Test Topics – Type 3 Recharging Techniques"},{"section":"TypeIII","question":"Low-pressure chillers are normally charged through the:","option_a":"Condenser charging valve","option_b":"Evaporator charging valve","option_c":"Compressor discharge service valve","option_d":"Purge unit connection","correct_answer":"B","explanation":"Standard practice is to charge through the evaporator side.","source_ref":"EPA Test Topics – Type 3 Recharging Techniques"},{"section":"TypeIII","question":"During evacuation of a low-pressure chiller, water must be circulated or drained from the tubes to prevent:","option_a":"Oil logging","option_b":"Freezing of water inside the tubes","option_c":"Excessive purge operation","option_d":"High head pressure","correct_answer":"A","explanation":"If water remains in the tubes while the refrigerant side is under deep vacuum, the water can freeze and rupture the tubes.","source_ref":"EPA Test Topics – Type 3 Recovery Techniques"},{"section":"TypeIII","question":"Complete recovery from a low-pressure appliance requires removal of:","option_a":"Only the liquid refrigerant","option_b":"Both liquid and vapor refrigerant","option_c":"Only the vapor refrigerant","option_d":"Only the oil","correct_answer":"B","explanation":"A significant amount of refrigerant remains as vapor after the liquid is removed; both must be recovered.","source_ref":"EPA Test Topics – Type 3 Recovery Techniques"},{"section":"TypeIII","question":"Recovery machines used with low-pressure appliances typically have a lower high-pressure cut-out setting because:","option_a":"Low-pressure refrigerants operate at much lower pressures than high-pressure refrigerants","option_b":"EPA requires the same cut-out for all machines","option_c":"It prevents oil from leaving the compressor","option_d":"It is only needed for R-11 systems","correct_answer":"A","explanation":"The cut-out is matched to the lower operating pressures of low-pressure refrigerants.","source_ref":"EPA Test Topics – Type 3"},{"section":"TypeIII","question":"Under ASHRAE Standard 15, machinery rooms containing R-123 require:","option_a":"Only a standard oxygen deprivation sensor","option_b":"A refrigerant-specific sensor in addition to general requirements","option_c":"No refrigerant detection equipment","option_d":"Only a combustible gas sensor","correct_answer":"B","explanation":"R-123 has a lower occupational exposure limit, so specific refrigerant detection is required.","source_ref":"EPA Test Topics – Type 3 Safety"},{"section":"TypeIII","question":"The primary purpose of a purge unit on a low-pressure chiller is to:","option_a":"Add make-up refrigerant automatically","option_b":"Remove non-condensable gases (mainly air) that enter the system","option_c":"Increase oil circulation to the compressor","option_d":"Cool the motor windings","correct_answer":"B","explanation":"Because low-pressure systems operate below atmospheric pressure, air can leak in. The purge unit extracts these non-condensables.","source_ref":"EPA Test Topics – Type 3 Refrigeration"},{"section":"TypeIII","question":"Recovery requirements for low-pressure appliances depend on:","option_a":"Only the brand of the chiller","option_b":"Whether the repair is major or non-major, whether the system is leaking, the amount of charge, and the age of the recovery equipment","option_c":"Only the ambient temperature","option_d":"Only the technician’s years of experience","correct_answer":"A","explanation":"EPA uses the same multi-factor approach for low-pressure systems as for high-pressure systems.","source_ref":"EPA Test Topics – Type 3 Recovery Requirements"},{"section":"TypeIII","question":"After the recovery machine reaches the required vacuum on a low-pressure system, the technician should:","option_a":"Immediately open the system to atmosphere","option_b":"Wait a few minutes to see whether pressure rises","option_c":"Charge liquid refrigerant right away","option_d":"Pressurize the system with oxygen","correct_answer":"B","explanation":"A pressure rise indicates that liquid refrigerant is still present and continuing to vaporize.","source_ref":"EPA Test Topics – Type 3"},{"section":"TypeIII","question":"Controlled hot water or a built-in heating device is preferred over nitrogen for leak-testing low-pressure chillers because:","option_a":"It raises pressure gently and stays well below the rupture-disc setting","option_b":"Nitrogen is prohibited by EPA","option_c":"Hot water is required by DOT shipping rules","option_d":"It simultaneously removes moisture","correct_answer":"A","explanation":"The method avoids the risk of over-pressurizing a system that has a very low-pressure relief device.","source_ref":"EPA Test Topics – Type 3 Leak Detection"},{"section":"TypeIII","question":"Appliances that are chronically leaking may be subject to:","option_a":"No additional requirements","option_b":"More frequent leak inspections and additional reporting obligations","option_c":"Automatic mandatory replacement within 30 days","option_d":"Service only by Type I technicians","correct_answer":"B","explanation":"EPA has specific provisions for chronically leaking appliances that increase monitoring and reporting duties.","source_ref":"EPA Test Topics – Type 3 Leak inspection and reporting"},{"section":"TypeIII","question":"Removing liquid refrigerant first from a low-pressure chiller:","option_a":"Slows down the recovery process","option_b":"Speeds up the overall recovery process","option_c":"Is not permitted","option_d":"Only works with R-123","correct_answer":"B","explanation":"As with high-pressure systems, liquid recovery transfers the bulk of the charge much faster than vapor recovery alone.","source_ref":"EPA Test Topics – Type 3 Recovery Techniques"},{"section":"TypeIII","question":"R-123 is most commonly found in:","option_a":"Residential split systems","option_b":"Low-pressure centrifugal chillers","option_c":"Domestic refrigerators","option_d":"Automotive air conditioning","correct_answer":"B","explanation":"R-123 has been a standard low-pressure centrifugal chiller refrigerant.","source_ref":"EPA Test Topics – Type 3"},{"section":"TypeIII","question":"The rupture disc on a low-pressure chiller protects the system from:","option_a":"Under-pressure conditions only","option_b":"Over-pressure conditions","option_c":"Oil foaming","option_d":"Electrical overload","correct_answer":"B","explanation":"It is a pressure-relief device that opens at a predetermined pressure.","source_ref":"EPA Test Topics – Type 3"},{"section":"TypeIII","question":"A technician who services low-pressure appliances must hold:","option_a":"Type I certification only","option_b":"Type III or Universal certification","option_c":"Type II certification only","option_d":"No special certification","correct_answer":"B","explanation":"Type III certification (or Universal) is required for low-pressure equipment.","source_ref":"40 CFR 82.161"},{"section":"TypeIII","question":"Failure to circulate or remove water from a low-pressure chiller during deep evacuation can result in:","option_a":"Improved heat transfer","option_b":"Freezing of water inside the evaporator or condenser tubes and possible tube damage","option_c":"Faster oil return","option_d":"Lower energy consumption","correct_answer":"A","explanation":"Water freezes at 32°F; under deep vacuum the refrigerant side can go well below that temperature.","source_ref":"EPA Test Topics – Type 3"},{"section":"TypeIII","question":"For non-major repairs on low-pressure systems, allowable methods of pressurizing the system include:","option_a":"Any pressure up to 100 psig with nitrogen","option_b":"Controlled hot water or the system’s own heating/pressurization device","option_c":"Open-flame heating","option_d":"Pressurization with pure oxygen","correct_answer":"B","explanation":"EPA specifies the acceptable methods that keep pressure safely low.","source_ref":"EPA Test Topics – Type 3"},{"section":"TypeIII","question":"The most common indicator of air entering a low-pressure system is:","option_a":"Low oil level","option_b":"Frequent or continuous operation of the purge unit","option_c":"High suction pressure only","option_d":"Quiet compressor operation","correct_answer":"A","explanation":"More air in the system causes the purge unit to run more often.","source_ref":"EPA Test Topics – Type 3"},{"section":"TypeIII","question":"Charging liquid refrigerant into the evaporator of a low-pressure chiller before the system pressure is raised sufficiently can cause:","option_a":"Faster charging with no side effects","option_b":"Freezing of water inside the tubes","option_c":"Better oil return","option_d":"Lower head pressure","correct_answer":"A","explanation":"Liquid refrigerant at low pressure can drop the tube temperature below freezing.","source_ref":"EPA Test Topics – Type 3 Recharging Techniques"},{"section":"TypeIII","question":"Recovery equipment intended for low-pressure appliances is designed with:","option_a":"The identical high-pressure cut-out settings used on Type II machines","option_b":"A lower high-pressure cut-out setting appropriate for low-pressure refrigerants","option_c":"No pressure controls at all","option_d":"Only vapor-recovery capability","correct_answer":"B","explanation":"The machine’s safety controls are matched to the lower pressure range of the refrigerants it will handle.","source_ref":"EPA Test Topics – Type 3"}]$epa_custom$::jsonb) as item(
  section text,
  question text,
  option_a text,
  option_b text,
  option_c text,
  option_d text,
  correct_answer text,
  explanation text,
  source_ref text
);

with normalized as (
  select
    case section
      when 'Core' then 'CORE'
      when 'TypeI' then 'TYPE_I'
      when 'TypeII' then 'TYPE_II'
      when 'TypeIII' then 'TYPE_III'
    end as section_code,
    question,
    explanation,
    source_ref
  from epa_custom_seed
)
insert into public.questions (
  public_id, section_id, topic_id, question_text, explanation,
  difficulty, reference, version, is_active
)
select
  md5('epa_custom:' || normalized.section_code || ':' || normalized.question)::uuid,
  sections.id,
  null,
  normalized.question,
  normalized.explanation,
  'medium',
  normalized.source_ref,
  1,
  true
from normalized
join public.certification_sections sections on sections.code = normalized.section_code
on conflict (public_id) do update set
  section_id = excluded.section_id,
  topic_id = excluded.topic_id,
  question_text = excluded.question_text,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  reference = excluded.reference,
  version = excluded.version,
  is_active = excluded.is_active,
  updated_at = timezone('utc', now());

with normalized as (
  select
    case seed.section
      when 'Core' then 'CORE'
      when 'TypeI' then 'TYPE_I'
      when 'TypeII' then 'TYPE_II'
      when 'TypeIII' then 'TYPE_III'
    end as section_code,
    seed.question,
    seed.correct_answer,
    choice.letter,
    choice.choice_text,
    choice.sort_order
  from epa_custom_seed seed
  cross join lateral (
    values
      ('A', seed.option_a, 1),
      ('B', seed.option_b, 2),
      ('C', seed.option_c, 3),
      ('D', seed.option_d, 4)
  ) as choice(letter, choice_text, sort_order)
)
insert into public.question_choices (id, question_id, choice_text, is_correct, sort_order)
select
  md5('epa_custom_choice:' || normalized.section_code || ':' || normalized.question || ':' || normalized.letter)::uuid,
  questions.id,
  normalized.choice_text,
  normalized.letter = normalized.correct_answer,
  normalized.sort_order
from normalized
join public.questions questions
  on questions.public_id = md5('epa_custom:' || normalized.section_code || ':' || normalized.question)::uuid
on conflict (id) do update set
  question_id = excluded.question_id,
  choice_text = excluded.choice_text,
  is_correct = excluded.is_correct,
  sort_order = excluded.sort_order,
  updated_at = timezone('utc', now());

commit;
